namespace Aion.GameServer.Tests;

public sealed class RetailNpcToUserNormalRecordCalculationTests
{
    public static IEnumerable<object[]> Cases()=>F.Corpus.RootElement.GetProperty("cases").EnumerateArray().Select(x=>new object[]{x.GetProperty("name").GetString()!});
    [Theory,MemberData(nameof(Cases))]
    public void CompleteRawContextsComputeTheirIndependentRecordWordsAndEntireRngState(string name)
    {
        Check(new F(name));
    }
    private static void Check(F f)
    {
        var row=f.Row;var e=row.GetProperty("expected");var outcome=C.CalculateFirstRecord(f.Input());
        if(!row.GetProperty("expected_admitted").GetBoolean())
        {Assert.False(outcome.Success);Assert.Null(outcome.Value);Assert.Equal("incomplete-child",outcome.Failure!.Code);Assert.Equal("target.forced_counter",outcome.Failure.Operand);return;}
        Assert.True(outcome.Success,outcome.Failure?.ToString());var r=outcome.Value!;
        Assert.Equal(e.GetProperty("record").GetInt32(),r.FinalRecordDamage);Assert.Equal(e.GetProperty("status").GetByte(),r.BaseStatus);
        Assert.Equal(e.GetProperty("critical").GetBoolean(),r.Critical);Assert.Equal(e.GetProperty("terminal").GetBoolean(),r.Terminal);Assert.Equal(e.GetProperty("element").GetInt32(),r.Element);
        uint header=r.BaseStatus switch{0=>0x80u,2=>0x40u,4=>0x20u,6=>0x100u,_=>0};Assert.Equal(header,r.Header);
        foreach(var word in e.GetProperty("steps").EnumerateObject())
        {
            if(word.Value.ValueKind!=JsonValueKind.String)continue;
            if(word.Name=="critical_multiplier"&&!r.Critical){Assert.False(r.FloatBits.ContainsKey(word.Name));continue;}
            Assert.True(r.FloatBits.TryGetValue(word.Name,out uint actual),"Missing independently expected stage "+word.Name);
            Assert.Equal(Convert.ToUInt32(word.Value.GetString(),16),actual);
        }
        var record=row.GetProperty("expected_pre_hp_record");
        Assert.Equal(Convert.FromBase64String(record.GetProperty("bytes_base64").GetString()!),r.RecordBytes.ToArray());
        Assert.Equal(Convert.FromBase64String(record.GetProperty("known_base64").GetString()!),r.RecordKnown.ToArray());
        Assert.Equal(record.GetProperty("header").GetUInt32(),r.Header);
        Assert.Equal(record.GetProperty("stage_sites").EnumerateArray().Select(x=>x.GetUInt64()),r.RandomCalls.Select(x=>x.CallerSite));
        var calls=e.GetProperty("calls").EnumerateArray().ToArray();Assert.Equal(calls.Length,r.RandomCalls.Length);
        for(int i=0;i<calls.Length;i++)
        {
            var want=calls[i];var actual=r.RandomCalls[i];Assert.Equal(want.GetProperty("stage").GetString(),actual.Stage);
            Assert.Equal(want.GetProperty("return").GetInt32(),actual.ComputedReturn);Assert.Equal(want.GetProperty("range")[0].GetInt32(),actual.First);Assert.Equal(want.GetProperty("range")[1].GetInt32(),actual.Second);
            var raw=want.GetProperty("raw").EnumerateArray().ToArray();Assert.Equal(raw.Length,actual.RawDraws.Length);
            for(int k=0;k<raw.Length;k++)
            {Assert.Equal(Convert.ToUInt64(raw[k].GetProperty("raw_u64").GetString(),16),actual.RawDraws[k].Value);Assert.Equal(raw[k].GetProperty("index_before").GetUInt32(),actual.RawDraws[k].IndexBefore);
                Assert.Equal(raw[k].GetProperty("accepted").GetBoolean(),actual.RawDraws[k].Disposition==RetailRandomDrawDisposition.Accepted);}
        }
        Assert.NotNull(r.RandomStateAfter);Assert.Equal(Convert.FromBase64String(e.GetProperty("rng_after").GetProperty("base64").GetString()!),r.RandomStateAfter.Bytes.ToArray());
        Assert.Equal(e.GetProperty("rng_after").GetProperty("sha256").GetString(),r.RandomStateAfter.Sha256);Assert.Equal(7ul+(ulong)calls.Length,r.RandomGenerationAfter);
        Assert.Equal(calls.Sum(x=>x.GetProperty("raw").GetArrayLength())*40L,r.RandomLogicalTraceBytes);
        Assert.Equal(row.GetProperty("clocks").EnumerateArray().Select(x=>x.GetProperty("role").GetString()),r.ConsumedClocks.Select(x=>x.Role.ToString()));
        var cursor=new U.Cursor(f.Context.Common,r.CalculatedMemory,1000);
        Assert.Equal(0u,cursor.U32(F.User+0x4094,0,"released User lock"));
        Assert.Equal(new byte[]{0xa5,0xa5,0xa5},r.RecordBytes.AsSpan(53,3).ToArray());Assert.Equal(new byte[]{0,0,0},r.RecordKnown.AsSpan(53,3).ToArray());
        Assert.All(r.RecordKnown.Take(53),x=>Assert.Equal((byte)1,x));Assert.Equal((uint)r.FinalRecordDamage,BinaryPrimitives.ReadUInt32LittleEndian(r.RecordBytes.AsSpan()));
        if(r.ConsumedClocks.Length==2)
        {
            ulong off=r.ConsumedClocks[1].Role switch{C.ClockRole.DodgeCounter=>0x13e4,C.ClockRole.ParryCounter=>0x13e0,C.ClockRole.ResistCounter=>0x13e8,_=>0x13dc};
            Assert.Equal(8000u,cursor.U32(F.User+off,0,"deadline"));
        }
        if(r.Terminal)Assert.Null(r.Pve);
        else{Assert.NotNull(r.Pve);Assert.Equal(0x3f800000u,r.Pve.RatioBits);Assert.True(Array.IndexOf(r.Pve.Reads.Select(x=>x.Operand).ToArray(),"User+774:slot60")<Array.IndexOf(r.Pve.Reads.Select(x=>x.Operand).ToArray(),"User+778:slot59"));}
        Assert.False(r.CurrentActorObserved);Assert.False(r.HostEffectsExecuted);Assert.False(r.WholeWorldAttackCompleted);Assert.False(r.HpApplied);Assert.False(r.ActivationReady);Assert.False(r.GlobalNativeRngOrderProved);
    }
    [Fact]
    public void InclusiveNormalCriticalEqualityIsCalculatedRatherThanCopiedFromTheSkillPath()
    {var f=new F("physical_critical_draw_equals500");var r=Good(f);Assert.True(r.Critical);Assert.Equal(256,r.FinalRecordDamage);Assert.Equal(500,r.RandomCalls[^1].ComputedReturn);Assert.Equal(500L,Assert.Single(r.Steps,x=>x.Operand=="critical.threshold").Value);}
    [Fact]
    public void ElementalTypeDoesNotSelectTheDefenseGroup()
    {var block=Good(new F("elemental_group0_block"));var resist=Good(new F("magical_group_resist"));Assert.Equal((byte)4,block.BaseStatus);Assert.Equal((byte)6,resist.BaseStatus);
        Assert.Equal(new[]{"Base","Dodge","Block","Critical"},block.RandomCalls.Select(x=>x.Stage));Assert.Equal(new[]{"Base","Resist"},resist.RandomCalls.Select(x=>x.Stage));}
    [Fact]
    public void CalculatedShieldHelperFalseContinuesToActualParry()
    {
        var f=new F("elemental_group0_block");f.W8(F.User+0x569c,0);f.W16(F.Primary,1);f.W32(F.Primary+0x1c8,0);f.W16(F.Backup,1);f.W32(F.Backup+0x1c8,0x20);
        // Eligibility checks backup despite occupied primary. Reduction selects live when
        // primary lacks ratio; absent live shield then returns false and reaches parry.
        f.Clocks=[f.Clocks[0]];var r=Good(f);Assert.Equal((byte)10,r.BaseStatus);Assert.Equal(157,r.FinalRecordDamage);
        Assert.Equal(new[]{"Base","Dodge","Block","Parry","Critical"},r.RandomCalls.Select(x=>x.Stage));Assert.DoesNotContain(r.Steps,x=>x.Operand=="shield.after");
        Assert.Equal(new[]{"03000000","00000000"},r.Steps.Where(x=>x.Kind=="Write"&&(x.Operand=="normal.shared_active"||x.Operand=="normal.shared_ordinary")).Select(x=>x.After));
    }
    [Theory]
    [InlineData(0x774ul,4)] [InlineData(0x778ul,4)] [InlineData(0x8008ul,8)] [InlineData(0x1492ul,2)] [InlineData(0x1494ul,4)]
    public void UnknownReachedUserOperandWithholdsEveryCandidate(ulong offset,int count)
    {var f=new F();f.Forget(F.User+offset,count);var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Null(o.Value);Assert.False(o.DiagnosticPrefixCommittable);}
    [Theory]
    [InlineData(0)] [InlineData(1)]
    public void SharedRngCapacityDoesNotResetAtTheSecondDraw(int rawBudget)
    {var f=new F();f.Limits=f.Limits with{MaxRawDraws=rawBudget};var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Null(o.Value);Assert.NotNull(o.DiagnosticRandomPrefix);Assert.False(o.DiagnosticPrefixCommittable);}
    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)]
    public void EveryDeclaredAdapterCapacityWithholdsTheWholeCandidate(int kind)
    {var f=new F();f.Limits=kind switch{0=>f.Limits with{MaxImages=f.Memory().Images.Length-1},1=>f.Limits with{MaxBytes=f.Memory().ByteCount-1},2=>f.Limits with{MaxSteps=1},_=>f.Limits with{MaxRandomOperations=1}};var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Null(o.Value);Assert.False(o.DiagnosticPrefixCommittable);}
    [Fact]
    public void UnusedClockObservationRejectsTheWholeRecord()
    {var f=new F();f.Clocks=f.Clocks.Add(f.Clocks[0]);var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Equal("tail",o.Failure!.Operand);Assert.Null(o.Value);}
    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)] [InlineData(5)]
    public void ClockMustBindOriginalRoleSiteActorLifetimeAndEpoch(int kind)
    {
        var f=new F();var tick=f.Clocks[0];f.Clocks=f.Clocks.SetItem(0,kind switch{0=>tick with{Role=C.ClockRole.BlockCounter},1=>tick with{CallerSite=0},2=>tick with{TickSite=0},3=>tick with{ActorAddress=F.Npc},4=>tick with{ActorGeneration="old"},_=>tick with{Epoch="old"}});
        var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Equal("clock",o.Failure!.Code);
    }
    [Fact]
    public void MovementIsComputedFromInlineWordsAndTheOriginalClock()
    {
        var f=new F();f.W8(F.User+0x408c,1);f.W32(F.User+0x4090,1333); //2000-1333=667 selects second flags.
        f.W32(0x141069ed0ul+28+4,100);var r=Good(f);Assert.Contains(r.Steps,x=>x.Kind=="ComputedGetter"&&x.Value==1);
        Assert.Equal(226,r.FinalRecordDamage);Assert.Equal(0u,new U.Cursor(f.Context.Common,r.CalculatedMemory,1000).U32(F.User+0x4094,0,"release"));
    }
    [Fact]
    public void ContendedMovementRetainsNoCommittablePrefix()
    {var f=new F();f.W32(F.User+0x4094,1);var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Equal("movement.contended_lock",o.Failure!.Operand);Assert.Null(o.Value);}
    [Fact]
    public void CounterDeadlineUsesTheOriginalUnsignedWrappingTick()
    {var f=new F("elemental_group0_parry");f.Clocks=f.Clocks.SetItem(1,f.Clocks[1] with{Value=uint.MaxValue-999});var r=Good(f);Assert.Equal((byte)2,r.BaseStatus);Assert.Equal(4000u,new U.Cursor(f.Context.Common,r.CalculatedMemory,1000).U32(F.User+0x13e0,0,"wrapping deadline"));}
    [Fact]
    public void CalculatedDodgeDoesNotReadCriticalPveOrClassOperands()
    {var f=new F(F.Corpus.RootElement.GetProperty("additional_contexts").EnumerateArray().Single(x=>x.GetProperty("name").GetString()=="computed_dodge_terminal"));f.Forget(F.User+0x774,8);f.Forget(F.User+0x14c8,8);f.Forget(F.Template+0x450,1);f.Forget(f.LookupCell,8);var r=Good(f);Assert.True(r.Terminal);Assert.Equal((byte)0,r.BaseStatus);Assert.Null(r.Pve);Assert.Equal(new[]{"Base","Dodge"},r.RandomCalls.Select(x=>x.Stage));}
    [Fact]
    public void ConditionalCurrentDeclarationCannotBecomeObservedOrExecuted()
    {var f=new F();f.Context=f.Context with{Common=f.Context.Common with{Origin=U.Origin.DeclaredCurrentSnapshot}};f.Random=f.Random with{Origin=RetailRandomInputOrigin.DeclaredCurrentMemory,Ownership=f.Random.Ownership! with{Origin=RetailRandomInputOrigin.DeclaredCurrentMemory}};Assert.False(Good(f).CurrentActorObserved);}
    [Fact]
    public void LateClassLookupReadsSelectedPointerBeforeItsCountRejection()
    {var f=new F();f.W32(0x14f398f40,0);f.Forget(f.LookupCell,8);var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Equal("class_lookup.selected_before_count_compare",o.Failure!.Operand);}
    [Fact]
    public void ClassNullSkipsExclusiveButAnActiveCurrentExclusiveWithholdsTheWholeCandidate()
    {var f=new F();f.W64(f.LookupCell,0);f.Forget(F.Template+0x450,1);Assert.Equal(256,Good(f).FinalRecordDamage);
        f.W64(f.LookupCell,F.Template);f.W8(F.Template+0x450,1);var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Equal("exclusive",o.Failure!.Operand);}
    [Fact]
    public void ActualRawHp2AbsoluteRowComputesNineteenAfterFloatRounding()
    {
        var f=new F();const ulong program=0x73000000;f.Add(program,32,"current HP2","program-life");f.W64(F.User+0x8008,program);f.W16(program+2,0x12);f.W16(program+6,100);f.W16(program+10,0x78);f.W8(program+8,1);f.W16(program+14,100);
        var r=Good(f);Assert.Equal(19,r.Pve!.Hp2Delta);Assert.Equal(0x419fffffu,r.Pve.FloatBits["absolute_product"]);
        f.Forget(program+12,2);Assert.False(C.CalculateFirstRecord(f.Input()).Success);
    }
    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)]
    public void ActiveOrUnknownOuterChildrenAreNeverSuppliedSuccessAnswers(int kind)
    {
        var f=new F();if(kind==0)f.W32(F.Npc+0x1250,0x20);else if(kind==1)f.W8(F.User+0x1ca4,2);else if(kind==2)f.W8(F.Npc+0x1688,1);else f.W32(0x142766278,4);
        var o=C.CalculateFirstRecord(f.Input());Assert.False(o.Success);Assert.Null(o.Value);Assert.True(o.Failure!.Unsupported);
    }
    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)]
    public void FloatingContractRequiresExplicitFiniteRneConditions(int kind)
    {var f=new F();f.Floating=kind switch{0=>f.Floating with{NearestEven=null},1=>f.Floating with{FlushToZero=true},2=>f.Floating with{DenormalsAreZero=true},_=>f.Floating with{NormalReturn=false}};Assert.False(C.CalculateFirstRecord(f.Input()).Success);}
    [Fact]
    public void NoSourceOrOutputCanAliasAnActorOrTheOwnedRngStorage()
    {var f=new F();var input=f.Input();var o=C.CalculateFirstRecord(input with{Boundary=input.Boundary with{WorldFrameRbp=F.User+0x80}});Assert.False(o.Success);Assert.Equal("alias",o.Failure!.Code);}
    public static IEnumerable<object[]> Additional()=>F.Corpus.RootElement.GetProperty("additional_contexts").EnumerateArray().Select(x=>new object[]{x.GetProperty("name").GetString()!});
    [Theory,MemberData(nameof(Additional))]
    public void SingletonRejectionRolloversAndDodgeUseEntireIndependentRawContexts(string name)
    {Check(new F(F.Corpus.RootElement.GetProperty("additional_contexts").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==name)));}
    [Fact]
    public void Standalone_entry_does_not_accept_a_World_guard_boolean_or_HP_pending_carrier()
    {
        var f=new F();var result=C.CalculateFirstRecord(f.Input());Assert.True(result.Success,result.Failure?.ToString());
        Assert.False(result.Value!.WholeWorldAttackCompleted);Assert.False(result.Value.HpApplied);
        Assert.Empty(typeof(Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcUserNormalWorldOwner.GuardAdmission).GetConstructors());
        Assert.Empty(typeof(Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcUserNormalCompletion.HpAdmission).GetConstructors());
    }

    private static C.Result Good(F f){var o=C.CalculateFirstRecord(f.Input());Assert.True(o.Success,o.Failure?.ToString());return o.Value!;}
}

internal sealed class NormalRecordFixture
{
    internal const ulong Npc=0x10000000,User=0x20000000,Template=0x30000000,Vector=0x60000000,Entry=0x61000000,
        Primary=0x70000000,Backup=0x71000000,Manager=0x72000000,Frame=0x80000080;
    private sealed record Bytes(ulong Address,byte[] Raw,byte[] Known,string Identity,string Life);
    private readonly List<Bytes> images=[];
    internal JsonElement Row{get;}
    internal RetailNpcTemplateInputs Projection{get;}
    internal A.Context Context;
    internal ImmutableArray<C.Clock> Clocks;
    internal RetailRandomTransaction Random;
    internal C.Limits Limits=new(128,8_000_000,30_000,30,1000,40_000);
    internal C.Floating Floating=new(true,true,false,false,true);
    internal C.Infrastructure Infrastructure=new(true,true,true);
    internal ulong LookupCell=>0x75000000ul+(ulong)(Projection.NpcId-200000)*8;
    internal static JsonDocument Corpus{get;}=Inflate(Embedded,"e4863ec382d9c4cc83526ed2ebfc87f7fcf6879a908d6cb2252d75949487b1f7");
    internal NormalRecordFixture(string name="physical_critical_draw_equals500") : this(Corpus.RootElement.GetProperty("cases").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==name)) { }
    internal NormalRecordFixture(JsonElement row)
    {
        Row=row;
        var source=Row.GetProperty("source");var profile=new RetailNpcSourceProfile(source.GetProperty("profile"));
        string id=source.GetProperty("dataset_id").GetString()!,manifest=source.GetProperty("output_manifest_sha256").GetString()!,region=source.GetProperty("region").GetString()!;
        var dataset=new RetailNpcStaticDataset(id,manifest,new Dictionary<int,RetailNpcSourceProfile>{{profile.NpcId,profile}},1,0,0,ImmutableArray<RetailNpcArtifactReceipt>.Empty,
            source.GetProperty("provenance"),source.GetProperty("manifest"));
        var projected=RetailNpcTemplateProjection.Project(dataset,profile.NpcId,new(id,manifest,region));Assert.True(projected.Success,string.Join(";",projected.Issues));Projection=projected.Inputs!;
        Context=new(new(U.RequiredSources,"constructed-normal-record","epoch1",U.Origin.ConstructedFixture,"independent full raw mathematical recipe"),A.ParentProof,A.NormalBodyProof,A.TypeTableProof,id,manifest,region);
        foreach(var image in Row.GetProperty("images").EnumerateArray())
        {
            byte[] raw=Convert.FromBase64String(image.GetProperty("raw_base64").GetString()!),known=Convert.FromBase64String(image.GetProperty("known_base64").GetString()!);
            Assert.Equal(image.GetProperty("raw_sha256").GetString(),U.Hash(raw));Assert.Equal(image.GetProperty("known_sha256").GetString(),U.Hash(known));
            images.Add(new(image.GetProperty("address").GetUInt64(),raw,known,image.GetProperty("identity").GetString()!,image.GetProperty("generation").GetString()!));
        }
        Clocks=Row.GetProperty("clocks").EnumerateArray().Select(x=>Clock(Enum.Parse<C.ClockRole>(x.GetProperty("role").GetString()!),Convert.ToUInt64(x.GetProperty("caller_site").GetString(),16),Convert.ToUInt64(x.GetProperty("tick_site").GetString(),16),x.GetProperty("value").GetUInt32())).ToImmutableArray();
        var initial=Row.GetProperty("rng_before");Random=new(RetailRandomInputOrigin.ConstructedFixture,7,[],Convert.FromBase64String(initial.GetProperty("base64").GetString()!).ToImmutableArray(),
            initial.GetProperty("sha256").GetString(),new(P.MainSha256,RetailRandomEngine.RngEvidenceSha256),
            new(RetailRandomInputOrigin.ConstructedFixture,"one ordered mathematical stream","rng-life","serialized owner","constructed current bytes",RetailRandomEngine.NativeEngineAddress,7,true),new(RetailRandomEngine.NativeEngineAddress,64,ulong.MaxValue));
    }
    internal C.Clock Clock(C.ClockRole role,ulong caller,ulong tick,uint value)=>new(role,caller,tick,value,User,Context.Common.Operation,Context.Common.Epoch,"user-life","constructed original-site tick");
    internal U.Memory Memory()=>U.Memory.Create(images.Select(x=>U.Image.Create(new(x.Address,x.Identity,x.Life,Context.Common),x.Raw,x.Known)));
    internal U.Cursor Cursor()=>new(Context.Common,Memory(),30_000);
    internal A.Admission Admit(int ordinal=0)=>A.SelectedNormal.Admit(Context,Projection,ordinal,Memory(),new(Npc,Template,"source-life","template-life","vector-life","entry-life"));
    internal C.Input Input()
    {var admitted=Admit();Assert.True(admitted.Success,admitted.Failure?.ToString());return new(Context,admitted.Value!,Memory(),new(User,Frame,"user-life","frame-life","computed first record boundary; no outer guard assertion"),Random,Clocks,Floating,Infrastructure,Limits);}
    internal void Add(ulong address,int size,string identity,string life="extra-life",byte fill=0)
    {Assert.DoesNotContain(images,x=>!(address+(ulong)size<=x.Address||x.Address+(ulong)x.Raw.Length<=address));images.Add(new(address,Enumerable.Repeat(fill,size).ToArray(),Enumerable.Repeat((byte)1,size).ToArray(),identity,life));}
    private (Bytes Image,int Offset) Locate(ulong address,int count)
    {var x=images.Single(x=>x.Address<=address&&address+(ulong)count<=x.Address+(ulong)x.Raw.Length);return(x,checked((int)(address-x.Address)));}
    internal void Put(ulong a,ReadOnlySpan<byte> value){var(x,i)=Locate(a,value.Length);value.CopyTo(x.Raw.AsSpan(i));x.Known.AsSpan(i,value.Length).Fill(1);}
    internal void Forget(ulong a,int count){var(x,i)=Locate(a,count);x.Known.AsSpan(i,count).Fill(0);}
    internal void W8(ulong a,byte value)=>Put(a,[value]);
    internal void W16(ulong a,ushort value){Span<byte>b=stackalloc byte[2];BinaryPrimitives.WriteUInt16LittleEndian(b,value);Put(a,b);}
    internal void W32(ulong a,uint value){Span<byte>b=stackalloc byte[4];BinaryPrimitives.WriteUInt32LittleEndian(b,value);Put(a,b);}
    internal void W64(ulong a,ulong value){Span<byte>b=stackalloc byte[8];BinaryPrimitives.WriteUInt64LittleEndian(b,value);Put(a,b);}
    private static JsonDocument Inflate(string encoded,string expected)
    {using var input=new MemoryStream(Convert.FromBase64String(encoded));using var zip=new GZipStream(input,CompressionMode.Decompress);using var output=new MemoryStream();zip.CopyTo(output);Assert.True(output.Length<=32_000_000);byte[] raw=output.ToArray();Assert.Equal(expected,U.Hash(raw));return JsonDocument.Parse(raw);}
